#include <vector>
#include <algorithm>

class Solution {
public:
    int minZeroArray(std::vector<int>& nums, std::vector<std::vector<int>>& queries) {
        int n = nums.size();
        bool all_zero = true;
        for (int x : nums) if (x != 0) { all_zero = false; break; }
        if (all_zero) return 0;

        auto check = [&](int k) {
            std::vector<long long> diff(n + 1, 0);
            for (int i = 0; i < k; ++i) {
                diff[queries[i][0]] += queries[i][2];
                diff[queries[i][1] + 1] -= queries[i][2];
            }
            long long curr = 0;
            for (int i = 0; i < n; ++i) {
                curr += diff[i];
                if (nums[i] > curr) return false;
            }
            return true;
        };

        int low = 1, high = queries.size(), ans = -1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (check(mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
};

class Solution {
    public int minZeroArray(int[] nums, int[][] queries) {
        int n = nums.length;
        boolean allZero = true;
        for (int x : nums) if (x != 0) { allZero = false; break; }
        if (allZero) return 0;

        int low = 1, high = queries.length, ans = -1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (check(mid, nums, queries, n)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }

    private boolean check(int k, int[] nums, int[][] queries, int n) {
        long[] diff = new long[n + 1];
        for (int i = 0; i < k; i++) {
            diff[queries[i][0]] += queries[i][2];
            diff[queries[i][1] + 1] -= queries[i][2];
        }
        long curr = 0;
        for (int i = 0; i < n; i++) {
            curr += diff[i];
            if (nums[i] > curr) return false;
        }
        return true;
    }
}

var minZeroArray = function(nums, queries) {
    const n = nums.length;
    if (nums.every(x => x === 0)) return 0;

    function check(k) {
        const diff = new Float64Array(n + 1);
        for (let i = 0; i < k; i++) {
            diff[queries[i][0]] += queries[i][2];
            diff[queries[i][1] + 1] -= queries[i][2];
        }
        let curr = 0;
        for (let i = 0; i < n; i++) {
            curr += diff[i];
            if (nums[i] > curr) return false;
        }
        return true;
    }

    let low = 1, high = queries.length, ans = -1;
    while (low <= high) {
        const mid = (low + high) >> 1;
        if (check(mid)) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return ans;
};
